def priority(item, bins):
    valid = bins >= item
    if not valid.any():
        return np.full(len(bins), -np.inf)
    gap = bins[valid] - item
    # Score based on 1/(gap) but penalized by gap and boosted by bin capacity
    scores = 1.0 / (gap + 1e-8) - 0.1 * (gap + 0.1) / (bins[valid] + 1e-8)
    # Favor bins with large remaining space (log capacity)
    scores += np.log(bins[valid] + 1)
    return np.concatenate([np.full(len(bins) - valid.sum(), -np.inf), scores])

